class DoublyLinkedList {
  private Node head;
  private Node tail;
  private int size;

  public DoublyLinkedList() {
    head = null;
    tail = null;
    size = 0;
  }

  public int size() {
    return size;
  }

  public void pushFront(int val) {
    Node newNode = new Node(val);
    if (head == null) {
      head = tail = newNode;
    } else {
      newNode.next = head;
      head.prev = newNode;
      head = newNode;
    }
    size++;
  }

  public Integer popFront() {
    if (head == null) {
      return null;
    }
    int val = head.val;
    head = head.next;
    if (head != null) {
      head.prev = null;
    } else {
      tail = null;
    }
    size--;
    return val;
  }

  public void pushBack(int val) {
    Node newNode = new Node(val);
    if (tail == null) {
      head = tail = newNode;
    } else {
      newNode.prev = tail;
      tail.next = newNode;
      tail = newNode;
    }
    size++;
  }

  public Integer popBack() {
    if (tail == null) {
      return null;
    }
    int val = tail.val;
    tail = tail.prev;
    if (tail != null) {
      tail.next = null;
    } else {
      head = null;
    }
    size--;
    return val;
  }

  public Node contains(int val) {
    Node cur = head;
    while (cur != null) {
      if (cur.val == val)
        return cur;
      cur = cur.next;
    }
    return null;
  }
}

